/*
 * GONE QUIET (DBU-08), once a day. QUIET is the one settings object for it.
 * For each learner on an active plan, the reasons that hold now:
 *   inactive  nothing for QUIET.inactiveDays, counted from her last activity, or from her plan's start if
 *             that is later (a learner enrolled yesterday is not quiet)
 *   overdue   a shared homework, not started, QUIET.overdueDays past its due time
 * One open flag per learner. No reasons: close it. Reasons and an open flag: refresh its reasons
 * (raisedAt, the snooze and the nudge stay). Reasons and no flag: raise one. A flag for someone no
 * longer on an active plan is closed. So a second run in a day changes nothing.
 * Rings a staff-only bell when anything changed, so an open inbox re-reads.
 */
(async () => {
  try {
    const QUIET = { inactiveDays: 7, overdueDays: 2 };
    const DAY = 86400000;
    const now = Date.now();
    const t = (iso) => { const n = Date.parse(iso || ''); return Number.isFinite(n) ? n : 0; };
    const R = Noodl.Records;
    const learners = Array.isArray(Inputs.learners) ? Inputs.learners : [];
    const open = (await R.query('QuietFlag', {}, { limit: 1000, plain: true })).filter((f) => !f.closedAt);
    const stamp = new Date(now).toISOString();
    let raised = 0;
    let closed = 0;
    let refreshed = 0;
    const bell = (learner) => R.create('Doorbell', { learner, topic: 'inbox' }, { acl: { 'role:staff': { read: true } } });

    for (const l of learners) {
      const reasons = [];
      const quietSince = Math.max(t(l.lastActiveAt), t(l.startedOn));
      if (now - quietSince >= QUIET.inactiveDays * DAY) reasons.push({ kind: 'inactive', lastActiveAt: l.lastActiveAt || null });
      for (const o of l.overdue || []) {
        if (now - t(o.dueAt) >= QUIET.overdueDays * DAY) reasons.push({ kind: 'overdue', stepId: o.stepId, title: o.title, dueAt: o.dueAt });
      }
      const mine = open.filter((f) => f.learner === l.learnerId);
      const [flag, ...extra] = mine;
      for (const x of extra) { await R.save(x.objectId, { closedAt: stamp }, { className: 'QuietFlag' }); closed += 1; }
      if (!reasons.length) {
        if (flag) { await R.save(flag.objectId, { closedAt: stamp }, { className: 'QuietFlag' }); closed += 1; await bell(l.learnerId); }
        continue;
      }
      if (flag) {
        if (JSON.stringify(flag.reasons || []) !== JSON.stringify(reasons)) {
          await R.save(flag.objectId, { reasons }, { className: 'QuietFlag' });
          refreshed += 1;
          await bell(l.learnerId);
        }
        continue;
      }
      await R.create('QuietFlag', { learner: l.learnerId, reasons, raisedAt: stamp, snoozedUntil: null, nudgedAt: null, closedAt: null }, { plain: true });
      raised += 1;
      await bell(l.learnerId);
    }
    const active = new Set(learners.map((l) => l.learnerId));
    for (const f of open.filter((x) => !active.has(x.learner))) {
      await R.save(f.objectId, { closedAt: stamp }, { className: 'QuietFlag' });
      closed += 1;
    }
    console.log('[dbu:morningRound] quiet: raised=' + raised + ' refreshed=' + refreshed + ' closed=' + closed);
    Outputs.raised = raised;
    Outputs.closed = closed;
    Outputs.request = { at: now, for: 'digest' };
  } catch (e) {
    console.error('[dbu:morningRound] quiet: ' + String((e && e.message) || e));
    Outputs.failed();
  }
})();

/*
 * THE MORNING DIGEST (DBU-08): one email to the coach when anything reached the inbox since the last
 * digest (Setting digestSentAt; the first ever looks back one day). Nothing new: nothing sent, and the
 * stamp stays. The stamp is claimed before the send and put back if the send fails, so a second run
 * the same morning sends nothing. To the coach address (Setting coachEmail, else the default), as
 * message mail is. Plain text; logs carry counts, never an address. Days are calendar days in Paris.
 * A check-in answered (DBU-10) is a line too; shared/Inbox items already lists those last.
 */
(async () => {
  let digest = 'none';
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const t = (iso) => { const n = Date.parse(iso || ''); return Number.isFinite(n) ? n : 0; };
    const dayNo = (ms) => Date.parse(new Date(ms).toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' }) + 'T00:00:00Z') / 86400000;
    const secret = (name) => {
      const s = globalThis._noodl_get_secret ? globalThis._noodl_get_secret(name) : null;
      return s && s.found ? String(s.value) : '';
    };
    const send = typeof globalThis._noodl_send_email === 'function' ? globalThis._noodl_send_email : null;
    const appUrl = secret('appUrl').replace(/\/+$/, '');
    const DEFAULT_COACH = 'coach@example.com';
    const now = new Date();
    const items = Array.isArray(Inputs.items) ? Inputs.items : [];

    const stampRows = await q('Setting', { key: { equalTo: 'digestSentAt' } });
    const row = stampRows[0] || null;
    const lastAt = row && row.value ? t(row.value) : now.getTime() - 86400000;
    const fresh = items.filter((i) => t(i.since) > lastAt);
    if (!fresh.length) {
      digest = 'nothing new';
    } else if (!send || !appUrl) {
      digest = 'no mailer or no appUrl secret';
      console.error('[dbu:morningRound] digest: no mailer or no appUrl secret (tools/setup-signin.mjs): nothing sent');
    } else {
      const settings = await q('Setting', { key: { equalTo: 'coachEmail' } });
      const to = (settings[0] && String(settings[0].value || '').trim()) || DEFAULT_COACH;
      const line = (i) => {
        if (i.kind === 'review') return '- ' + i.learner + ' handed in "' + i.title + '"' + (i.version > 1 ? ' (version ' + i.version + ')' : '');
        if (i.kind === 'question') return '- ' + i.learner + (i.count > 1 ? ' wrote ' + i.count + ' messages: "' : ' asked: "') + i.body + '"';
        if (i.kind === 'checkin') return '- ' + i.learner + ' answered the check-in "' + i.title + '"';
        const days = dayNo(now.getTime()) - dayNo(Math.max(t(i.facts && i.facts.lastActiveAt), t(i.facts && i.facts.startedOn)));
        const overdue = (i.reasons || []).filter((r) => r.kind === 'overdue').map((r) => '"' + r.title + '"');
        const parts = [];
        if ((i.reasons || []).some((r) => r.kind === 'inactive')) parts.push('no sign of ' + i.first + ' for ' + days + ' days');
        if (overdue.length) parts.push(overdue.join(', ') + ' overdue');
        return '- ' + i.learner + ' has gone quiet: ' + parts.join('; ');
      };
      const subject = fresh.length === 1 ? '1 new thing in your inbox' : fresh.length + ' new things in your inbox';
      const text = [
        'Good morning. New since the last digest:',
        '',
        ...fresh.map(line),
        '',
        items.length === fresh.length ? '' : items.length + ' waiting in all.',
        'Open your inbox: ' + appUrl + '/coach/inbox',
        '',
        '--',
        'Sent once a morning by Digital Bricks University, only when something new is waiting.'
      ].filter((x, k, a) => !(x === '' && a[k - 1] === '')).join('\n');

      const claim = async (value) => {
        if (row) await R.save(row.objectId, { value }, { className: 'Setting' });
        else if (value) await R.create('Setting', { key: 'digestSentAt', value }, { plain: true });
      };
      await claim(now.toISOString());
      let ok = false;
      let why = '';
      try {
        const res = await send({ to, subject, text });
        ok = !!(res && res.success);
        why = ok ? '' : String((res && res.error) || 'no answer');
      } catch (e) {
        why = String((e && e.message) || e);
      }
      if (ok) digest = 'sent ' + fresh.length;
      else {
        if (row) await claim(row.value || '');
        else {
          const made = await q('Setting', { key: { equalTo: 'digestSentAt' } });
          for (const m of made) await R.save(m.objectId, { value: '' }, { className: 'Setting' });
        }
        digest = 'send failed';
        console.error('[dbu:morningRound] digest send failed, tomorrow tries again: ' + why.slice(0, 160).replace(/[^\s]+@[^\s]+/g, '<address>'));
      }
    }
  } catch (e) {
    digest = 'failed';
    console.error('[dbu:morningRound] digest: ' + String((e && e.message) || e));
  }
  console.log('[dbu:morningRound] digest: ' + digest);
  Outputs.digest = digest;
  Outputs.done();
})();
